namespace NIMI.UniPortal.Abstractions.Files;

/// <summary>
/// Where uploaded files live (P7). Modules store only the returned key; the key is generated by the storage and never
/// contains user input (rule R3). The host provides one implementation (local disk today, object storage in DEP).
/// </summary>
public interface IFileStorage
{
    Task<StoredFile> SaveAsync(Stream content, string fileName, string contentType, CancellationToken cancellationToken);

    /// <summary>Opens the stored file for reading; the caller disposes the stream. Unknown key → FileNotFoundException.</summary>
    Task<Stream> OpenReadAsync(string key, CancellationToken cancellationToken);

    Task DeleteAsync(string key, CancellationToken cancellationToken);
}
